  // Intensity 0..1 -> layers: other always, bass from 0.25, drums from 0.5, vocals from 0.75
  // Per-layer control: {drums: {on: true, vol: 1}, ...}
  setLayers(layers) {
    this.layers = layers;
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // ramp the per-chunk stem gains of every live/scheduled chunk
    for (const rec of this.sources) {
      if (!rec.stemGains) continue;
      for (const name of ['drums', 'bass', 'other', 'vocals']) {
        const gn = rec.stemGains[name];
        if (!gn) continue;
        const st = layers[name] || {
          on: true,
          vol: 1
        };
        const target = st.on ? st.vol : 0;
        gn.gain.cancelScheduledValues(now);
        gn.gain.setValueAtTime(gn.gain.value, now);
        gn.gain.linearRampToValueAtTime(target, now + 0.35);
      }
    }
  }
