    const opts = {
      linearFade: isRepeat
    };
    if (!isRepeat && this.bassSwap) opts.bassDelay = Math.max(xf, 0.01);
    const d1 = this._scheduleChunkRange(f1, t1, when, 0.03, xf > 0 ? xf : null, {
      linearFade: true
    });
